steps.analogousExample:
/* Similar: styling all elements of a type */
section {
  background-color: lightblue;
}
div {
  background-color: lightcoral;
}

/* Similar: scoping styles to a specific section */
@scope (.sidebar) to (.main-content) {
    /* Styles here only apply within .sidebar but stop at .main-content */
}

/* Similar: scoped paragraph styling */
@scope (.container) {
    p {
        background-color: lightgray;
    }
}

/* Similar: another @scope rule with different styling */
@scope (.alternate-section) to (.regular-section) {
    p {
        color: darkblue;
        font-weight: bold;
    }
}

/* Example of using :scope within @scope */
@scope (.container) {
    :scope {
        border: 2px solid green;
    }
}

/* Example: scoped rule with higher specificity */
@scope (.card) {
  .card p {
    color: blue;
  }
}

/* Example of multiple @scope rules creating isolated contexts */
@scope (.card) {
  h2 { color: blue; }
  p { margin: 1em; }
}

@scope (.sidebar) {
  h2 { color: green; }
  p { font-size: 0.9rem; }
}
